// PRIMARY: crates/consensus/common/src/validation.rs:validate_block_pre_execution (lines 144-173)
pub fn validate_block_pre_execution<B, ChainSpec>(
    block: &SealedBlock<B>,
    chain_spec: &ChainSpec,
) -> Result<(), ConsensusError>
{
    post_merge_hardfork_fields(block, chain_spec)?;
    // Check transaction root
    if let Err(error) = block.ensure_transaction_root_valid() {
        return Err(ConsensusError::BodyTransactionRootDiff(error.into()))
    }
    // EIP-7825 validation
    if chain_spec.is_osaka_active_at_timestamp(block.timestamp()) {
        for tx in block.body().transactions() {
            if tx.gas_limit() > MAX_TX_GAS_LIMIT_OSAKA {
                return Err(TxGasLimitTooHighErr { ... }.into());
            }
        }
    }
    Ok(())
}
